import React from "react";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { Layout } from "./components/layout/Layout";
import ScrollToTop from "./components/ScrollToTop";

// Core
import { Home } from "./pages/Home";
import { PackShip } from "./pages/PackShip";

// Pack & Ship
import { ArtworkShipping } from "./pages/ArtworkShipping";
import { BicycleShipping } from "./pages/BicycleShipping";
import { GolfClubShipping } from "./pages/GolfClubShipping";
import { FedExShipping } from "./pages/FedExShipping";
import { UPSAuthorizedShipperOutlet } from "./pages/UPSAuthorizedShipperOutlet";
import { USPSServices } from "./pages/USPSServices";
import { DHLExpress } from "./pages/DHLExpress";
// import { InternationalShippingPage } from "./pages/InternationalShippingPage";
import { PackageDropOffs } from "./pages/PackageDropOffs";
import { PackageReceiving } from "./pages/PackageReceiving";
import { CustomBoxMaking } from "./pages/CustomBoxMaking";
import { ProfessionalPacking } from "./pages/ProfessionalPacking";
import { PackagingSupplies } from "./pages/PackagingSupplies";
import { PostageStamps } from "./pages/PostageStamps";

// Copy & Print
import { BusinessCardsPage } from "./pages/BusinessCardsPage";
import { FlyersBrochures } from "./pages/FlyersBrochures";
import { PostersPrinting } from "./pages/PostersPrinting";
import { PostcardPrinting } from "./pages/PostcardPrinting";
// import { PosterBannerPrinting } from "./pages/PosterBannerPrinting";
import { DocumentPrinting } from "./pages/DocumentPrinting";
// import { DocumentFinishing } from "./pages/DocumentFinishing";
import { GraphicDesign } from "./pages/GraphicDesign";
import { Copies } from "./pages/Copies";

// Home & Business
import { MailboxRentalPage } from "./pages/MailboxRentalPage";
import { DigitalMailboxRental } from "./pages/DigitalMailboxRental";
import { EveryDoorDirectMail } from "./pages/EveryDoorDirectMail";
import { Shredding } from "./pages/Shredding";
import { DocumentScanning } from "./pages/DocumentScanning";
import { FaxServices } from "./pages/FaxServices";
// import { NotaryServices } from "./pages/NotaryServices";

// Specialty
import { DigitalFingerprinting } from "./pages/DigitalFingerprinting";
import { Insurance } from "./pages/Insurance";

// Service Landing Pages
import { CopyPrint } from "./pages/CopyPrint";
import { HomeBusiness } from "./pages/HomeBusiness";

// Additional Pages
import { AboutUs } from "./pages/AboutUs";
import { ContactUs } from "./pages/ContactUs";
import { Services } from "./pages/Services";
import { Tracking } from "./pages/Tracking";
import { ServiceAreaPage } from "./pages/ServiceAreaPage";
import { ServiceAreaIndex } from "./pages/ServiceAreaIndex";
import { Privacy } from "./pages/Privacy";
import { Terms } from "./pages/Terms";
import ShippingPartners from "./pages/ShippingPartners";
import AskMailboxPlus from "./pages/ask-mailbox-plus";
import { NotFound } from "./pages/NotFound";

const DebugRoutes: React.FC = () => {
  const location = useLocation();
  console.log('Current location:', location.pathname);
  return null;
};

const App: React.FC = () => {
  console.log('App.tsx: App component rendering');
  return (
    <Router>
      <ScrollToTop />
      <Layout>
        <DebugRoutes />
        <React.Suspense fallback={<div style={{padding: 32, textAlign: "center"}}>Loading…</div>}>
        <Routes>
        {/* Homepage */}
        <Route path="/" element={<Home />} />

        {/* Service Landing Pages */}
        <Route path="/copy-print" element={<CopyPrint />} />
        <Route path="/home-business" element={<HomeBusiness />} />

        {/* Pack & Ship Landing Page */}
        <Route path="/pack-ship" element={<PackShip />} />

        {/* Pack & Ship */}
        <Route path="/pack-ship/artwork-shipping" element={<ArtworkShipping />} />
        <Route path="/pack-ship/bicycle-shipping" element={<BicycleShipping />} />
        <Route path="/pack-ship/golf-club-shipping" element={<GolfClubShipping />} />
        <Route path="/pack-ship/fedex-shipping" element={<FedExShipping />} />
        <Route path="/pack-ship/ups-authorized-shipper-outlet" element={<UPSAuthorizedShipperOutlet />} />
        <Route path="/pack-ship/usps-services" element={<USPSServices />} />
        <Route path="/pack-ship/dhl-express" element={<DHLExpress />} />
        {/* <Route path="/pack-ship/international-shipping" element={<InternationalShippingPage />} /> */}
        <Route path="/pack-ship/package-drop-offs" element={<PackageDropOffs />} />
        <Route path="/pack-ship/package-receiving" element={<PackageReceiving />} />
        <Route path="/pack-ship/custom-box-making" element={<CustomBoxMaking />} />
        <Route path="/pack-ship/professional-packing" element={<ProfessionalPacking />} />
        <Route path="/pack-ship/packaging-supplies" element={<PackagingSupplies />} />
        <Route path="/pack-ship/postage-stamps" element={<PostageStamps />} />

        {/* Copy & Print */}
        <Route path="/copy-print/business-cards" element={<BusinessCardsPage />} />
        <Route path="/copy-print/flyers-brochures" element={<FlyersBrochures />} />
        <Route path="/copy-print/posters-printing" element={<PostersPrinting />} />
        <Route path="/copy-print/postcard-printing" element={<PostcardPrinting />} />
        { /* <Route path="/copy-print/poster-banner-printing" element={<PosterBannerPrinting />} /> */ }
        <Route path="/copy-print/document-printing" element={<DocumentPrinting />} />
        <Route path="/copy-print/graphic-design" element={<GraphicDesign />} />
        <Route path="/copy-print/copies" element={<Copies />} />

        {/* Home & Business */}
        <Route path="/home-business/mailbox-rental" element={<MailboxRentalPage />} />
        <Route path="/home-business/digital-mailbox-rental" element={<DigitalMailboxRental />} />
        <Route path="/home-business/every-door-direct-mail" element={<EveryDoorDirectMail />} />
        <Route path="/home-business/shredding" element={<Shredding />} />
        <Route path="/home-business/document-scanning" element={<DocumentScanning />} />
        <Route path="/home-business/fax-services" element={<FaxServices />} />
        {/* <Route path="/home-business/notary-services" element={<NotaryServices />} /> */}

        {/* Specialty */}
        <Route path="/specialty/digital-fingerprinting" element={<DigitalFingerprinting />} />
        <Route path="/specialty/insurance" element={<Insurance />} />

        {/* Additional Pages */}
        <Route path="/about-us" element={<AboutUs />} />
        <Route path="/contact-us" element={<ContactUs />} />
        <Route path="/services" element={<Services />} />
        <Route path="/tracking" element={<Tracking />} />
        <Route path="/service-area" element={<ServiceAreaIndex />} />
        <Route path="/service-area/:slug" element={<ServiceAreaPage />} />
        <Route path="/shipping-partners" element={<ShippingPartners />} />
        <Route path="/ask-mailbox-plus" element={<AskMailboxPlus />} />
        <Route path="/privacy" element={<Privacy />} />
        <Route path="/terms" element={<Terms />} />

        {/* Catch-all route for unmatched paths */}
        <Route path="*" element={<NotFound />} />
        </Routes>
        </React.Suspense>
      </Layout>
    </Router>
  );
};

export default App;

import React from "react";
import { getServiceImageUrl } from "../lib/supabase";

export const CarrierLogos: React.FC = () => {
  const carriers = [
    {
      name: "FedEx",
      logo: getServiceImageUrl("fedex-logo.webp"),
      url: "https://www.fedex.com/",
    },
    {
      name: "UPS",
      logo: getServiceImageUrl("ups-logo.webp"),
      url: "https://www.ups.com/",
    },
    {
      name: "USPS",
      logo: getServiceImageUrl("usps-logo.webp"),
      url: "https://www.usps.com/",
    },
    {
      name: "DHL",
      logo: getServiceImageUrl("dhl-logo.webp"),
      url: "https://www.dhl.com/",
    },
  ];

  return (
    <div className="flex flex-wrap items-center justify-center gap-8 sm:gap-12 mt-10 mb-8 px-4">
      {carriers.map((carrier) => (
        <a
          key={carrier.name}
          href={carrier.url}
          target="_blank"
          rel="noopener noreferrer"
          className="transition-transform duration-200 hover:scale-105"
        >
          <img
            src={carrier.logo}
            alt={carrier.name}
            width={200}
            height={64}
            className="h-12 sm:h-16 w-auto object-contain drop-shadow-md"
            loading="lazy"
          />
        </a>
      ))}
    </div>
  );
};

import React from 'react';

interface JsonLdProps {
  schema: object;
}

export const JsonLd: React.FC<JsonLdProps> = ({ schema }) => {
  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{
        __html: JSON.stringify(schema, null, 2),
      }}
    />
  );
};

import React from "react";
import { Helmet } from "react-helmet-async";
import { siteConfig } from "../config/siteConfig";

interface MetaProps {
  title: string;
  description: string;
  keywords?: string;
  canonical?: string;
  schema?: object | object[];
  ogImage?: string;
  geoRegion?: string;
  geoPlacename?: string;
  geoPosition?: string;
  icbm?: string;
  themeColor?: string;
  robots?: string;
}

export const Meta: React.FC<MetaProps> = ({
  title,
  description,
  keywords,
  canonical,
  schema,
  ogImage,
  geoRegion,
  geoPlacename,
  geoPosition,
  icbm,
  themeColor,
  robots = "index, follow"
}) => {
  const schemas = Array.isArray(schema) ? schema : schema ? [schema] : [];

  return (
    <Helmet>
      <title>{title}</title>
      <meta name="description" content={description} />
      <meta name="robots" content={robots} />
      {keywords && <meta name="keywords" content={keywords} />}
      {canonical && <link rel="canonical" href={canonical} />}

      {/* Open Graph */}
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:type" content="website" />
      <meta property="og:site_name" content={siteConfig.name} />
      {canonical && <meta property="og:url" content={canonical} />}
      {ogImage && <meta property="og:image" content={ogImage} />}

      {/* Twitter Cards */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      {ogImage && <meta name="twitter:image" content={ogImage} />}

      {/* Geo & Locale meta for local SEO */}
      {geoRegion && <meta name="geo.region" content={geoRegion} />}
      {geoPlacename && <meta name="geo.placename" content={geoPlacename} />}
      {geoPosition && <meta name="geo.position" content={geoPosition} />}
      {icbm && <meta name="ICBM" content={icbm} />}

      {/* Favicons / theme color */}
      <link rel="icon" type="image/png" sizes="32x32" href={siteConfig.favicon.icon32} />
      <link rel="icon" type="image/png" sizes="16x16" href={siteConfig.favicon.icon16} />
      <link rel="apple-touch-icon" sizes="180x180" href={siteConfig.favicon.appleTouch} />
      <link rel="icon" type="image/png" sizes="192x192" href={siteConfig.favicon.android192} />
      <link rel="icon" type="image/png" sizes="512x512" href={siteConfig.favicon.android512} />
      {themeColor && <meta name="theme-color" content={themeColor} />}

      {/* JSON-LD Structured Data */}
      {schemas.map((s, i) => (
        <script
          key={i}
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(s) }}
        />
      ))}
    </Helmet>
  );
};

import { useEffect } from "react";
import { useLocation } from "react-router-dom";

const ScrollToTop: React.FC = () => {
  const { pathname } = useLocation();

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);

  return null;
};

export default ScrollToTop;

import React from "react";
import { motion } from "framer-motion";
import { Star } from "lucide-react";

// ✅ Barrel imports
import { Meta, Breadcrumbs, JsonLd, VisitUsButton } from "../components";
import { CarrierLogos } from "./CarrierLogos";
import { Service } from "../types/services";
import { siteConfig } from "../config/siteConfig";
import { getWebPageSchema, getServiceSchema, getFAQSchema } from "../utils/schema";
import { getGoogleMapsLink } from "../utils/location";

// ✅ Shadcn UI
import {
  Accordion,
  AccordionItem,
  AccordionTrigger,
  AccordionContent,
} from "./ui/accordion";

export const ServicePage: React.FC<Service> = (props) => {
  const {
    pageTitle,
    metaDescription,
    keywords,
    slug,
    serviceName,
    city,
    heroTitle,
    heroSubtitle,
    heroImage,
    content = [],
    features = [],
    faqs = [],
    // cta, // Removed: not in Service type
  } = props;

  // ✅ Sort featured first, then by order if present
  const sortedFaqs = [...faqs].sort((a, b) => {
    if (a.isFeatured && !b.isFeatured) return -1;
    if (!a.isFeatured && b.isFeatured) return 1;
    if (a.order !== undefined && b.order !== undefined) return a.order - b.order;
    if (a.order !== undefined) return -1;
    if (b.order !== undefined) return 1;
    return 0;
  });

  // ✅ Flatten FAQs into a single list without category separation
  const groupedFaqs = { All: sortedFaqs };

  const url = `${siteConfig.domain}/${slug}`;

  return (
    <div className="bg-white">
      {/* ✅ Metadata */}
      <Meta
        title={pageTitle}
        description={metaDescription}
        keywords={keywords}
        // slug={slug} // Removed: not a prop of Meta
      />

      {/* ✅ Structured Data */}
      <JsonLd schema={getWebPageSchema(siteConfig, { name: pageTitle, description: metaDescription, url })} />
      <JsonLd schema={getServiceSchema(siteConfig, { serviceName, url })} />
      {faqs?.length ? <JsonLd schema={getFAQSchema(siteConfig, faqs.map(faq => ({ question: faq.question, answer: faq.answer })))} /> : null}

      {/* ✅ Breadcrumbs */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <Breadcrumbs service={props} />
      </div>

      {/* ✅ Hero Section */}
      <section className="relative bg-[#0855B1] py-16 lg:py-24 text-center overflow-hidden">
        {heroImage && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 0.25 }}
            transition={{ duration: 0.8 }}
            className="absolute inset-0 z-0"
          >
            <img
              src={heroImage}
              alt={heroTitle}
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-black/40" />
          </motion.div>
        )}

        <div className="relative z-10 max-w-4xl mx-auto px-6">
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="text-4xl md:text-6xl lg:text-7xl font-extrabold text-white tracking-tight mb-6"
          >
            {heroTitle}
          </motion.h1>
          {heroSubtitle && (
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8 }}
              className="text-lg text-gray-200 leading-relaxed"
            >
              {heroSubtitle}
            </motion.p>
          )}
        </div>
      </section>

      {/* ✅ Content Sections */}
      {content.length > 0 && (
        <section className="bg-white py-16 lg:py-24">
          <div className="max-w-5xl mx-auto px-6 grid md:grid-cols-2 gap-8">
            {content.map((block, i) => (
              block.isFullWidth ? (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.6 }}
                  viewport={{ once: true }}
                  className="md:col-span-2 bg-white p-8 border border-gray-200 rounded-2xl shadow-sm"
                >
                  <h2 className="text-2xl font-bold text-[#0855B1] mb-4">{block.heading}</h2>
                  <p className="text-gray-700 leading-relaxed whitespace-pre-line" dangerouslySetInnerHTML={{ __html: block.body }}></p>
                </motion.div>
              ) : (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.6, delay: i * 0.1 }}
                  viewport={{ once: true }}
                  className="bg-[#F9FAFB] rounded-2xl border border-gray-200 p-6 shadow-sm hover:shadow-md transition-shadow"
                >
                  <h2 className="text-xl font-semibold text-[#0855B1] mb-3">
                    {block.heading}
                  </h2>
                  <p className="text-gray-700 leading-relaxed" dangerouslySetInnerHTML={{ __html: block.body }}></p>
                </motion.div>
              )
            ))}
          </div>
        </section>
      )}

      {/* WHY CHOOSE US SECTION */}
      {features.length > 0 && (
        <section className="py-16 bg-gray-50">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
            <h2 className="text-3xl md:text-4xl font-bold text-[#111827] mb-10">
              Why Choose Us
            </h2>

            <div className="flex flex-wrap justify-center gap-6">
              {features.map((feature, index) => (
                <div
                  key={index}
                  className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 w-full sm:w-72 text-center"
                >
                  <h3 className="text-lg font-semibold text-[#111827] mb-2">
                    {feature.title}
                  </h3>
                  <p className="text-sm text-[#4B5563]">{feature.description}</p>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* ✅ FAQ Section */}
      {faqs.length > 0 && (
        <section className="bg-white py-16 lg:py-24">
          <div className="max-w-4xl mx-auto px-6">
            <h2 className="text-3xl font-bold text-[#111827] mb-8 text-center">
              Frequently Asked Questions
            </h2>

            {Object.entries(groupedFaqs).map(([category, items]) => (
              <div key={category} className="mb-10">
                <Accordion type="single" collapsible className="w-full space-y-4">
                  {items.map((faq, i) => (
                    <AccordionItem
                      key={faq.id || i}
                      value={`faq-${faq.id || i}`}
                      className={`border rounded-xl shadow-sm ${
                        faq.isFeatured
                          ? "bg-[#F0F7FF] border-[#0855B1]"
                          : "bg-white"
                      }`}
                    >
                      <AccordionTrigger className="px-4 py-3 text-left font-semibold text-[#0855B1] hover:underline">
                        <span className="flex items-center gap-2">
                          {faq.isFeatured && (
                            <Star className="w-4 h-4 fill-[#0855B1] text-[#0855B1]" />
                          )}
                          {faq.question}
                        </span>
                      </AccordionTrigger>
                      <AccordionContent className="px-4 pb-4 text-[#4B5563] leading-relaxed">
                        {faq.answer}
                        {faq.lastUpdated && (
                          <p className="mt-2 text-sm text-gray-400">
                            Last updated:{" "}
                            {new Date(faq.lastUpdated).toLocaleDateString()}
                          </p>
                        )}
                      </AccordionContent>
                    </AccordionItem>
                  ))}
                </Accordion>
              </div>
            ))}
          </div>
        </section>
      )}
{/* Carrier Logos */}
<CarrierLogos />

      {/* ✅ CTA Section */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <a
            href={getGoogleMapsLink("directions", siteConfig.name)}
            target="_blank"
            rel="noopener noreferrer"
          >
            <VisitUsButton
              defaultCity={city}
              className="bg-white !text-[#0855B1] hover:bg-gray-100 hover:!text-[#064080]"
            />
          </a>
        </div>
      </section>
    </div>
  );
};

import React from "react";

interface SmartImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  /**
   * If true, loads image eagerly with high fetch priority (for LCP/hero).
   * Otherwise, loads lazily by default.
   */
  priority?: boolean;
  /**
   * Optionally provide AVIF/WebP sources for responsive images.
   */
  sources?: Array<{
    srcSet: string;
    type: string;
    media?: string;
  }>;
}

/**
 * SmartImage: Responsive, lazy-loading image with AVIF/WebP support.
 * - Use priority for LCP/hero images.
 * - Uses <picture> if sources are provided.
 */
export const SmartImage: React.FC<SmartImageProps> = ({
  priority = false,
  sources,
  ...imgProps
}) => {
  const loading = priority ? "eager" : "lazy";
  const fetchPriority = priority ? "high" : undefined;
  const decoding = "async";

  if (sources && sources.length > 0) {
    return (
      <picture>
        {sources.map((source, i) => (
          <source
            key={i}
            srcSet={source.srcSet}
            type={source.type}
            media={source.media}
          />
        ))}
        <img
          {...imgProps}
          loading={loading}
          fetchPriority={fetchPriority}
          decoding={decoding}
        />
      </picture>
    );
  }

  return (
    <img
      {...imgProps}
      loading={loading}
      fetchPriority={fetchPriority}
      decoding={decoding}
    />
  );
};

export default SmartImage;

import React, { useState, useEffect } from "react";
import { Button } from "./ui";

interface VisitUsButtonProps {
  defaultCity: string; // e.g., "Concord Township"
  className?: string;
}

export const VisitUsButton: React.FC<VisitUsButtonProps> = ({ defaultCity, className }) => {
  const [userCity, setUserCity] = useState(defaultCity);

  useEffect(() => {
    if (!navigator.geolocation) return;

    const updateCity = async (latitude: number, longitude: number) => {
      try {
        const res = await fetch(
          `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}`
        );
        const data = await res.json();
        const address = data.address;

        // Prefer city -> town -> village -> county/state
        const city =
          address?.city ||
          address?.town ||
          address?.village ||
          address?.county ||
          address?.state ||
          defaultCity;

        // If city is very small (like a village), prepend "near"
        const displayCity =
          address?.village || address?.town ? `near ${city}` : city;

        setUserCity(displayCity);
      } catch {
        setUserCity(defaultCity);
      }
    };

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        updateCity(latitude, longitude);
      },
      () => {
        setUserCity(defaultCity); // fallback if permission denied
      },
      { enableHighAccuracy: true, maximumAge: 0, timeout: 10000 }
    );

    return () => navigator.geolocation.clearWatch(watchId);
  }, [defaultCity]);

  return <Button className={className}>Visit Us from {userCity}</Button>;
};

import React from 'react';
import { Link } from 'react-router-dom';
import { Phone, Mail, MapPin } from 'lucide-react';
import { siteConfig } from '../../config/siteConfig';
import { getServiceImageUrl } from '../../lib/supabase';
import { SmartImage } from '../SmartImage';
import { getGoogleMapsLink } from '../../utils/location';

export const Footer: React.FC = () => {
  const quickLinks = [
    { name: 'Pack & Ship', href: '/pack-ship' },
    { name: 'Copy & Print', href: '/copy-print' },
    { name: 'Shipping Partners', href: '/shipping-partners' },
    { name: 'Ask Mailbox Plus', href: '/ask-mailbox-plus' },
  ];

  // ✅ Supabase logo URL
  const logoUrl = getServiceImageUrl('/images/mailbox_plus_logo.webp');

  return (
    <footer className="bg-white border-t border-gray-200">
      {/* Global Tagline */}
      <div className="bg-[#F9FAFB] border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 text-center">
          <h3 className="text-2xl font-semibold text-[#0855B1]">
            {siteConfig.tagline}
          </h3>
        </div>
      </div>

      {/* Footer Content */}
