import React from 'react';
import { Header } from './Header';
import { Footer } from './Footer';
import { JsonLd } from '../JsonLd';
import { getLocalBusinessSchema, getWebSiteSchema } from '../../utils/schema';
import { siteConfig } from '../../config/siteConfig';

interface LayoutProps {
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ children }) => {
  // console.log('Layout.tsx: Layout component rendering');
  const origin = (siteConfig.domain || "").replace(/\/+$/, ""); // remove trailing slash
  const localBusinessSchema = getLocalBusinessSchema(siteConfig);
  const webSiteSchema = getWebSiteSchema(siteConfig, `${origin}/search?q={search_term_string}`);

  return (
    <>
      {/* JSON-LD Schemas */}
      <JsonLd schema={localBusinessSchema} />
      <JsonLd schema={webSiteSchema} />

      <div className="min-h-screen bg-[#F9FAFB] flex flex-col">
        <Header />
        <main className="flex-1">
          {children}
        </main>
        <Footer />
      </div>
    </>
  );
};

import React from "react";
import type { CTA } from "../../types/services";
import { Button } from "../ui";
import { cn } from "../../lib/utils";
import { ArrowRight } from "lucide-react";
import { Link } from "react-router-dom";

interface Props {
  cta: CTA;
  className?: string;
}

export const CTASection: React.FC<Props> = ({ cta, className }) => {
  const {
    title,
    subtitle,
    buttonText,
    buttonLink,
    icon: Icon = ArrowRight,
    bgImage,
    align = "center",
    variant = "brand",
  } = cta;

  const alignment =
    align === "left"
      ? "text-left items-start"
      : "text-center items-center";

  // Basic variants; can be expanded in your design system
  const shell =
    variant === "neutral"
      ? "bg-white border border-gray-200"
      : variant === "ghost"
      ? "bg-transparent border border-[#0855B1]/20"
      : "bg-[#0855B1] text-white"; // brand default

  // Optional: Analytics event handler
  const handleClick = () => {
    if (window.plausible) {
      window.plausible("cta_click", {
        props: {
          page: window.location.pathname,
          title,
          buttonText,
        },
      });
    }
  };

  return (
    <section
      className={cn(
        "relative rounded-2xl overflow-hidden shadow-sm mt-12",
        shell,
        className
      )}
      aria-label="Call to action"
    >
      {bgImage && (
        <div
          aria-hidden
          className="absolute inset-0 opacity-20"
          style={{
            backgroundImage: `url(${bgImage})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
      )}
      <div className="relative px-6 py-12 flex flex-col gap-4 justify-center">
        <div className={cn("flex flex-col gap-3", alignment)}>
          <h2 className="text-2xl md:text-3xl font-bold">{title}</h2>
          {subtitle && (
            <p className="text-base md:text-lg opacity-90 max-w-2xl">
              {subtitle}
            </p>
          )}
          <div className="mt-4">
            {buttonLink.startsWith("http") ? (
              <a
                href={buttonLink}
                target="_blank"
                rel="noopener noreferrer"
                onClick={handleClick}
              >
                <Button variant={variant === "ghost" ? "ghost" : "primary"}>
                  {buttonText} <Icon size={18} />
                </Button>
              </a>
            ) : (
              <Link
                to={buttonLink}
                onClick={handleClick}
              >
                <Button variant={variant === "ghost" ? "ghost" : "primary"}>
                  {buttonText} <Icon size={18} />
                </Button>
              </Link>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

import React from "react";
import { Link } from "react-router-dom";
import { ChevronRight } from "lucide-react";
import { Service } from "../../types/services";
import { getServiceBreadcrumbs } from "../../utils/services-helpers";
import { JsonLd } from "../JsonLd";

interface BreadcrumbsProps {
  service: Service;
  baseUrl?: string;
}

export const Breadcrumbs: React.FC<BreadcrumbsProps> = ({
  service,
  baseUrl = "",
}) => {
  const items = getServiceBreadcrumbs(service, baseUrl);

  return (
    <>
      {/* Visible + microdata breadcrumbs */}
      <nav aria-label="Breadcrumb" className="mb-6">
        <ol
          className="flex items-center space-x-2 text-sm text-gray-600 overflow-x-auto"
          itemScope
          itemType="https://schema.org/BreadcrumbList"
        >
          {items.map((item, index) => (
            <li
              key={item.url}
              className="flex items-center"
              itemProp="itemListElement"
              itemScope
              itemType="https://schema.org/ListItem"
            >
              {index > 0 && (
                <ChevronRight
                  className="w-4 h-4 mx-1 text-gray-400"
                  aria-hidden="true"
                />
              )}

              {index < items.length - 1 ? (
                <Link
                  to={item.url}
                  itemProp="item"
                  itemScope
                  itemType="https://schema.org/Thing"
                  itemID={item.url}
                  className="hover:text-[#0855B1] transition-colors"
                >
                  <span itemProp="name">{item.name}</span>
                </Link>
              ) : (
                <span
                  className="font-semibold text-[#111827]"
                  aria-current="page"
                  itemProp="item"
                  itemScope
                  itemType="https://schema.org/Thing"
                  itemID={item.url}
                >
                  <span itemProp="name">{item.name}</span>
                </span>
              )}

              <meta itemProp="position" content={(index + 1).toString()} />
            </li>
          ))}
        </ol>
      </nav>

      {/* JSON-LD breadcrumbs */}
      <JsonLd
        schema={{
          "@context": "https://schema.org",
          "@type": "BreadcrumbList",
          itemListElement: items.map((item, index) => ({
            "@type": "ListItem",
            position: index + 1,
            item: {
              "@type": "Thing",
              "@id": item.url,
              name: item.name,
            },
          })),
        }}
      />
    </>
  );
};

import React from "react";
import { motion, type MotionProps } from "framer-motion";

type BaseButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & MotionProps;

interface ButtonProps extends BaseButtonProps {
  variant?: "primary" | "secondary" | "link" | "ghost";
  size?: "sm" | "md" | "lg";
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({
  variant = "primary",
  size = "md",
  children,
  className = "",
  ...props
}) => {
  const baseClasses =
    "inline-flex items-center justify-center gap-2 font-semibold transition-all duration-200 focus:outline-none focus:ring-4 disabled:opacity-50 disabled:cursor-not-allowed";

  const sizeClasses = {
    sm: "px-4 py-2 text-sm rounded-lg",
    md: "px-6 py-3 text-sm rounded-xl",
    lg: "px-8 py-4 text-base rounded-xl",
  };

  const variantClasses = {
    primary:
      "bg-[#0855B1] text-white hover:bg-[#064A9B] hover:shadow-lg focus:ring-[#B2D3EB] shadow-md",
    secondary:
      "border-2 border-[#0855B1] text-[#0855B1] bg-white hover:bg-[#F0F7FF] hover:border-[#064A9B] hover:shadow-md focus:ring-[#B2D3EB]",
    link:
      "text-[#0855B1] hover:text-[#064A9B] focus:ring-[#B2D3EB] p-0 bg-transparent shadow-none",
    ghost:
      "bg-transparent text-[#0855B1] hover:bg-[#F0F7FF] focus:ring-[#B2D3EB] shadow-none",
  };

  return (
    <motion.button
      whileHover={{
        scale: variant === "link" || variant === "ghost" ? 1 : 1.03,
        transition: { duration: 0.2 },
      }}
      whileTap={{ scale: variant === "link" || variant === "ghost" ? 1 : 0.97 }}
      className={`${baseClasses} ${sizeClasses[size]} ${variantClasses[variant]} ${className}`}
      {...props}
    >
      {children}
    </motion.button>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, X } from 'lucide-react';

interface SearchResult {
  title: string;
  description: string;
  href: string;
  category: string;
}

const searchData: SearchResult[] = [
  // ... your searchData (unchanged)
];

export const SearchBox: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const searchRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (query.trim() === '') {
      setResults([]);
      return;
    }

    const filteredResults = searchData.filter(item =>
      item.title.toLowerCase().includes(query.toLowerCase()) ||
      item.description.toLowerCase().includes(query.toLowerCase()) ||
      item.category.toLowerCase().includes(query.toLowerCase())
    ).slice(0, 8); // Limit to 8 results

    setResults(filteredResults);
  }, [query]);

  const handleSearchClick = () => {
    setIsOpen(true);
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  const handleResultClick = () => {
    setIsOpen(false);
    setQuery('');
    setResults([]);
  };

  const clearSearch = () => {
    setQuery('');
    setResults([]);
    inputRef.current?.focus();
  };

  return (
    <motion.div ref={searchRef} className="relative">
      {/* Search Button/Input */}
      <div className="relative">
        <button
          type="button"
          onClick={handleSearchClick}
          aria-expanded={isOpen}
          aria-haspopup="dialog"
          aria-controls="search-results"
          className={`flex items-center gap-2 px-4 py-2 rounded-xl border transition-all duration-200 ${
            isOpen
              ? 'border-[#0855B1] bg-white shadow-lg w-80'
              : 'border-gray-300 bg-white hover:border-[#0855B1] hover:shadow-sm w-48'
          }`}
        >
          <span className="sr-only">
            {isOpen ? 'Focus the service search input' : 'Open service search'}
          </span>
          <Search className="w-4 h-4 text-[#4B5563]" />
          {isOpen ? (
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search services..."
              className="flex-1 outline-none text-sm text-[#111827] placeholder-[#4B5563]"
            />
          ) : (
            <span className="text-sm text-[#4B5563]">Search services...</span>
          )}
          {isOpen && query && (
            <button
              type="button"
              onClick={clearSearch}
              className="p-1 hover:bg-gray-100 rounded-full transition-colors"
              aria-label="Clear search query"
            >
              <X className="w-3 h-3 text-[#4B5563]" />
            </button>
          )}
        </button>
      </div>

      {/* Search Results Dropdown */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="absolute top-full left-0 right-0 mt-2 bg-white border border-gray-200 rounded-xl shadow-lg z-50 max-h-96 overflow-y-auto"
            id="search-results"
          >
            {results.length > 0 ? (
              <div className="py-2">
                {results.map((result) => (
                  <Link
                    key={result.href}
                    to={result.href}
                    onClick={handleResultClick}
                    className="block px-4 py-3 hover:bg-[#F9FAFB] transition-colors border-b border-gray-100 last:border-b-0"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <h4 className="text-sm font-semibold text-[#111827] mb-1">
                          {result.title}
                        </h4>
                        <p className="text-xs text-[#4B5563] leading-relaxed">
                          {result.description}
                        </p>
                      </div>
                      <span className="text-xs text-[#0855B1] font-medium ml-3 flex-shrink-0">
                        {result.category}
                      </span>
                    </div>
                  </Link>
                ))}
              </div>
            ) : query.trim() !== '' ? (
              <div className="py-8 text-center">
                <p className="text-sm text-[#4B5563]">No services found for "{query}"</p>
                <p className="text-xs text-[#4B5563] mt-1">
                  Try searching for shipping, printing, or business services
                </p>
              </div>
            ) : (
              <div className="py-4 px-4">
                <p className="text-sm font-medium text-[#111827] mb-3">Popular Services</p>
                <div className="space-y-2">
                  {searchData.slice(0, 6).map((item) => (
                    <Link
                      key={item.href}
                      to={item.href}
                      onClick={handleResultClick}
                      className="block text-sm text-[#4B5563] hover:text-[#0855B1] transition-colors"
                    >
                      {item.title}
                    </Link>
                  ))}
                </div>
              </div>
            )}
        </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

